import fs from "node:fs";

// ─────────────────────────────────────────────────────────────────────────────
// Correctif header NDC — anti-débordement + regroupement des actions +
// boutons Portail Client / Contact élargis.
//
// Problème : entre 901px et ~1280px, la nav desktop (6 liens + 2 chevrons +
// Portail + Contact + FR/EN) réclamait ~1190px alors que le conteneur était
// plafonné à 1160px, sans réduction du gap/typo avant le burger (900px).
// => header tassé / débordant sur les laptops 13-15".
//
// Ce script réécrit app/globals.css avec :
//   1. Conteneur header élargi (1240px) + liens en nowrap.
//   2. Réduction progressive gap/police/padding aux paliers 1280px et 1080px.
//   3. Filet de séparation entre les liens de nav et le cluster d'actions.
//   4. Boutons Portail Client / Contact plus larges (padding horizontal accru).
//
// Usage dans StackBlitz :  node header-fix.mjs   puis commit + push.
// ─────────────────────────────────────────────────────────────────────────────

const files = {
  "app/globals.css": "",
};

for (const [path, b64] of Object.entries(files)) {
  const dir = path.substring(0, path.lastIndexOf("/"));
  if (dir) fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path, Buffer.from(b64, "base64").toString("utf8"));
  console.log("✓ écrit :", path);
}

console.log("\nCorrectif header appliqué. Pense à commit + push.");
